insert into public.questions(lesson_id,prompt,options,correct,explanation,position) values
('poland-grammar','Что лучше начинает связный рассказ о поездке?','["Najpierw pojechaliśmy do Gdańska.","Na końcu pojechaliśmy najpierw.","Potem przed początkiem Gdańsk."]',0,'Najpierw вводит первое событие рассказа.',0),
('poland-grammar','Najpierw zwiedziliśmy muzeum, ___ poszliśmy na rynek.','["potem","ponieważ","ale najpierw"]',0,'Potem показывает следующее действие в хронологической последовательности.',1),
('poland-grammar','___ kupiliśmy bilety, weszliśmy do muzeum.','["Kiedy","Na końcu","Dlatego"]',0,'Kiedy связывает действие или момент с последующим событием.',2),
('poland-grammar','Составьте: Сначала мы осмотрели замок, а затем пошли на рынок.','["Najpierw zwiedziliśmy zamek, a następnie poszliśmy na rynek.","Następnie najpierw zamek poszliśmy rynek.","Zwiedzaliśmy na końcu, ponieważ rynek."]',0,'Najpierw …, a następnie … ясно передаёт порядок двух действий.',3),
('poland-grammar','Как естественно завершить рассказ?','["Na końcu wróciliśmy pociągiem do domu.","Najpierw na końcu wracamy wczoraj.","Kiedy koniec, dlatego pociąg."]',0,'Na końcu вводит последнее событие и завершает последовательность.',4),
('poland-quiz','Что означает zabytek?','["исторический памятник","расписание","побережье"]',0,'Zabytek — исторически или культурно ценный объект.',0),
('poland-quiz','Gdzie leży Gdańsk?','["nad polskim wybrzeżem","w Tatrach","na południe od Krakowa"]',0,'Гданьск расположен на балтийском побережье Польши.',1),
('poland-quiz','Festiwal ___ w czerwcu.','["odbywa się","zwiedza","podróżuje się region"]',0,'О событии говорят: festiwal odbywa się — фестиваль проходит.',2),
('poland-quiz','Как сказать «местные жители»?','["lokalni mieszkańcy","stoliczne zabytki","górskie podróże"]',0,'Lokalni mieszkańcy — жители конкретного места.',3),
('poland-quiz','Najpierw byliśmy w muzeum, a ___ zjedliśmy obiad.','["później","zanim najpierw","dlatego że koniec"]',0,'Później продолжает хронологический рассказ.',4),
('poland-quiz','Что можно zwiedzać?','["stare miasto","tradycję wczoraj","podróż pociągiem jako czas"]',0,'Zwiedzać можно город, музей, замок и другие места.',5),
('poland-quiz','Выберите естественное описание Польши.','["Na północy jest morze, a na południu są góry.","Morze jest pod górami w stolicy.","Region świętuje pociągiem krajobraz."]',0,'Польское побережье находится на севере, а горные районы — на юге.',6),
('poland-quiz','Как завершить рассказ о празднике?','["Na końcu wszyscy obejrzeli koncert.","Najpierw koniec ogląda koncert.","Kiedy wszyscy, potem ponieważ."]',0,'Na końcu естественно вводит заключительное событие.',7),
('poland-reading-check','Dokąd pojechała grupa Mai?','["Do Torunia","Do Zakopanego","Do Gdańska"]',0,'Группа Майи отправилась на однодневную поездку в Торунь.',0),
('poland-reading-check','Co grupa zrobiła najpierw?','["Spotkała się z przewodniczką na rynku","Kupiła pierniki na dworcu","Wróciła do szkoły"]',0,'Первым событием была встреча с экскурсоводом на площади.',1),
('poland-reading-check','Czego uczniowie dowiedzieli się w muzeum?','["Jak dawniej przygotowywano pierniki","Jak buduje się statki","Jak chodzić po górach"]',0,'В музее они узнали о старом способе приготовления пряников.',2),
('poland-reading-check','Dlaczego na rynku było dużo ludzi?','["Odbywał się lokalny festiwal","Przyjechał pociąg","Muzeum było zamknięte"]',0,'На площади проходил местный фестиваль.',3),
('poland-reading-check','Co Maja zapamiętała z wyjazdu?','["Historię miasta i atmosferę festiwalu","Tylko czas podróży","Adres szkolnej biblioteki"]',0,'Майе запомнились история Торуни и атмосфера местного события.',4);
